#!/usr/bin/env python3
"""Add reviewed extracts from web-opened user-supplied leaderboard URLs."""
from pathlib import Path
from cmu_rag.io import digest, read_jsonl, write_jsonl

OUT = 'data/raw/leaderboard-user-urls/verified-extracts.jsonl'
CHECKED = '2026-10-25'
FACTS = [
('2','Steelers 2026 schedule announcement','https://www.steelers.com/news/steelers-release-2026-schedule','Pittsburgh Steelers','The Pittsburgh Steelers published their 2026 schedule on May 15, 2026. The team says the 17-game slate includes four primetime games, an NFL Paris game against the New Orleans Saints, and a home Black Friday game against the Denver Broncos. Pittsburgh opens at home against Atlanta on September 13, 2026. Source: Steelers.com official schedule announcement.'),
('3,92','Pittsburgh Improv November 2026 calendar','https://improv.com/calendar/pittsburgh/nov-2026/','Pittsburgh Improv','The Pittsburgh Improv November 2026 calendar lists Marcus D. Wiley on Nov. 1; Charles McBee on Nov. 4; T.J. Miller Nov. 5–7; Mark Paul Nov. 8; MC Hammersmith Nov. 12; Mo\'nique Nov. 13–14; T. Murph Nov. 15; Sam Morril Nov. 19–21; Christopher Titus Nov. 22; Collin Chamberlin Nov. 25; and ISMO Nov. 27–29. Times and event availability should be rechecked on the live calendar. Source: Pittsburgh Improv.'),
('4','Heinz History Center about and history','https://www.heinzhistorycenter.org/about/','Senator John Heinz History Center','The Senator John Heinz History Center is Pennsylvania’s largest history museum and a Smithsonian affiliate. Its museum family includes the Heinz History Center, Franco Harris Sports Museum, Fort Pitt Museum, and Meadowcroft Rockshelter and Historic Village. Its roots trace to 1879, when the Old Residents of Pittsburgh and Western Pennsylvania established a historical society. Source: official About page.'),
('5','Pittsburgh Pirates City Connect uniform','https://news.sportslogos.net/2023/06/22/pittsburgh-pirates-unveil-new-city-connect-uniform-bleeding-black-and-gold/baseball/','SportsLogos.Net News','The Pittsburgh Pirates unveiled their Nike MLB City Connect uniform on June 22, 2023. The design was described as a tribute to Pittsburgh, its people, industries, architecture, and future: a gold jersey with small repeating city symbols that fade toward a black “PGH” chest mark, plus a black collar and sleeve trim. Source: SportsLogos.Net News.'),
('6','Duquesne Incline historic context','https://pabook.libraries.psu.edu/literary-cultural-heritage-map-pa/feature-articles/duquesne-incline-historic-artifact-rise','Pennsylvania Center for the Book','The Duquesne Incline is a funicular railway that moves two cabins on a connecting cable over a pulley, with one cabin ascending while the other descends. The Pennsylvania Center for the Book article explains that Pittsburgh’s 19th-century industrial growth brought workers to Mt. Washington (then Coal Hill), while difficult hillside commutes motivated the construction of inclines. Source: Pennsylvania Center for the Book, Fall 2010.'),
('7','Phipps Conservatory opening and benefactor','https://www.phipps.conservatory.org/visit-and-explore/explore/explore-our-history/the-story-of-phipps/a-gift-to-pittsburgh-1893-1930','Phipps Conservatory and Botanical Gardens','Phipps Conservatory was a gift to Pittsburgh from philanthropist Henry W. Phipps. The Victorian glasshouse, designed by Lord & Burnham, was completed in August 1893 and opened to the public on December 7, 1893, with more than 6,000 plants from the World’s Columbian Exposition. Source: Phipps official history.'),
('9','Powdermill Nature Reserve location and admission','https://carnegiemnh.org/visit-powdermill/','Carnegie Museum of Natural History','Powdermill Nature Reserve is Carnegie Museum of Natural History’s environmental research center, located in Rector, Pennsylvania, 55 miles southeast of Pittsburgh. The field station and laboratory supports long-term studies of natural populations in western Pennsylvania. Its public trails and nature center are open for visitors, and admission is free. Source: Carnegie Museum of Natural History.'),
('12','Mohammed Sami at A History of the Carnegie International','https://www.luhringaugustine.com/highlights/mohammed-sami-a-history-of-the-carnegie-international','Luhring Augustine','Luhring Augustine reports that Mohammed Sami’s painting “23 Years of Night” (2022) is on view in the Carnegie Museum of Art’s ongoing exhibition series A History of the Carnegie International. The installation brings together works acquired from the International’s first iteration in 1896 through the 2022 edition. Source: Luhring Augustine gallery page.'),
('13','Radim Zohorna claimed off waivers','https://www.nhl.com/flames/news/flames-claim-radim-zohorna-off-waivers-336013818','Calgary Flames','The Calgary Flames announced on October 3, 2022 that they claimed forward Radim Zohorna off waivers from the Pittsburgh Penguins. The 6-foot-6, 220-pound winger had spent the previous two years splitting time between Pittsburgh and its AHL affiliate, Wilkes-Barre/Scranton. Source: Calgary Flames official release.'),
('15','Robert Morris club hockey 2026–27 schedule','https://rmuclubsports.com/sports/mens-ice-hockey/schedule/2026-27','Robert Morris University Club Sports','Robert Morris University Club Sports publishes a 2026–27 Men’s D1 Club Ice Hockey schedule. The official page lists home games at Colonial Arena, Island Sports Center, along with away games. The listed schedule includes a Nov. 20 game against Duquesne at 9 p.m. and a Nov. 21 home game against West Virginia at 8 p.m.; times and schedule changes should be confirmed on the live page. Source: RMU Club Sports.'),
('16,55,114','Carnegie Mellon University founding history','https://www.cmu.edu/about/history','Carnegie Mellon University','Carnegie Mellon’s official history says Andrew Carnegie donated $1 million to the city of Pittsburgh in 1900 to establish Carnegie Technical Schools, envisioned to teach practical skills, trades, and crafts. The first class was admitted in 1906. The institution later became Carnegie Mellon University. Source: CMU History.'),
('17','University of Pittsburgh 2026 Winter Commencement','https://www.commencement.pitt.edu/','University of Pittsburgh Commencement','The University of Pittsburgh commencement page lists the 2026 university-wide Winter Commencement for Sunday, December 13, 2026 at 3 p.m. at Petersen Events Center. It lists the Doctoral Hooding Ceremony for Wednesday, December 9, 2026 at 4 p.m. at Victory Heights Arena. Source: official Pitt Commencement page; schedules can change.'),
('18','Paintings in Carnegie Museum of Art','https://commons.wikimedia.org/wiki/Paintings_in_the_Carnegie_Museum_of_Art','Wikimedia Commons','The Wikimedia Commons page “Paintings in the Carnegie Museum of Art” identifies the Carnegie Museum of Art as located in Pittsburgh, United States, and established in 1896. The page organizes files by categories and variable parameters. Individual artwork attribution should be verified against the linked collection record. Source: Wikimedia Commons.'),
('20','Neil Walker and the Pirates resurgence','https://www.mlb.com/news/neil-walker-enjoying-pirates-resurgence/c-143050230','MLB.com','MLB.com’s August 14, 2015 article describes Neil Walker’s perspective on the Pittsburgh Pirates’ resurgence. It says Pittsburgh won three consecutive division titles in the early 1990s, then had 20 consecutive losing seasons before returning to the postseason in 2013. Walker grew up in Pittsburgh and played for the Pirates. Source: MLB.com.'),
]

def main():
    rows=[]
    for q,title,url,source,text in FACTS:
        rows.append({'id':'leaderboard-url-extract-'+digest(q+'\n'+url+'\n'+text)[:24], 'kind':'curated_source_record',
          'question_id':q,'source':'user-url-verified-extract','url':url,'aliases':[url], 'title':title,
          'text':text,'text_hash':digest(text),'source_checked_on':CHECKED,'extractor':'browser-open-reviewed-extract-v1',
          'provenance':[{'page_url':url,'method':'verified page text extracted by browser and summarized'}]})
    old=[]
    if Path(OUT).exists(): old=read_jsonl(OUT)
    byid={x['id']:x for x in old}
    byid.update({x['id']:x for x in rows})
    write_jsonl(OUT,byid.values())
    print(f'Wrote {len(rows)} verified extracts to {OUT}')
if __name__=='__main__': main()
